<script setup>
import {computed,reactive,ref,onMounted} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {readCapabilities,requestPasswordRecovery,resetPassword} from '../../../shared/application/workspace.js';
import {t} from '../../../shared/presentation/i18n.js';
import {errorText} from '../../../shared/presentation/feedback.js';
const route=useRoute(),router=useRouter(),resetting=computed(()=>route.path==='/reset-password');
const token=ref(typeof route.query.token==='string'?route.query.token:''),draft=reactive({email:'',password:'',confirm:''});
const available=ref(null),busy=ref(false),done=ref(false),error=ref('');
onMounted(async()=>{try{available.value=(await readCapabilities()).passwordRecovery;}catch(failure){error.value=errorText(failure);available.value=false;}});
async function submit(){if(busy.value)return;error.value='';busy.value=true;try{if(resetting.value){if(draft.password!==draft.confirm)throw Error('passwordMismatch');await resetPassword({token:token.value,password:draft.password});draft.password='';draft.confirm='';token.value='';await router.replace('/reset-password');}else await requestPasswordRecovery(draft.email);done.value=true;}catch(failure){error.value=errorText(failure);}finally{busy.value=false;}}
</script>
<template><div class="access-layout"><section class="access-story"><div class="eyebrow light">FRÍOTRACK</div><h1>{{t('recoverAccess')}}</h1><p>{{t('recoveryHelp')}}</p></section><section class="access-form"><h2>{{t(resetting?'resetPassword':'forgotPassword')}}</h2><PMessage v-if="done" severity="success" role="status">{{t(resetting?'passwordResetDone':'recoveryRequested')}}</PMessage><form v-else @submit.prevent="submit"><PMessage v-if="!resetting&&available===false" severity="warn">{{t('recoveryUnavailable')}}</PMessage><template v-if="resetting"><PMessage v-if="!token" severity="warn">{{t('invalidResetToken')}}</PMessage><div class="field"><label for="new-password">{{t('password')}}</label><PInputText id="new-password" v-model="draft.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"/></div><div class="field"><label for="reset-confirm">{{t('confirmPassword')}}</label><PInputText id="reset-confirm" v-model="draft.confirm" type="password" required minlength="12" maxlength="128" autocomplete="new-password"/></div></template><div v-else class="field"><label for="recovery-email">{{t('email')}}</label><PInputText id="recovery-email" v-model="draft.email" type="email" required maxlength="140" autocomplete="email"/></div><PMessage v-if="error" severity="error" role="alert">{{error}}</PMessage><PButton type="submit" :label="t(resetting?'resetPassword':'sendRecovery')" :loading="busy" :disabled="busy||(resetting?!token:available!==true)" class="full-width"/></form><div class="access-links"><RouterLink to="/login">{{t('backToLogin')}}</RouterLink></div></section></div></template>
